import inspect
from functools import partial

class MyDep:
    def __call__(self):
        pass

c = MyDep
p = partial(c)
# Mocking wrap (which usually happens via functools.wraps)
def wrap(f):
    def wrapper(*args, **kwargs):
        return f(*args, **kwargs)
    wrapper.__wrapped__ = f
    return wrapper

w = wrap(c)

def _impartial(func):
    while isinstance(func, partial):
        func = func.func
    return func

def _unwrapped_call(call):
    if call is None:
        return call
    return inspect.unwrap(_impartial(call))

print(f"isclass(_impartial(c)): {inspect.isclass(_impartial(c))}")
print(f"isclass(_unwrapped_call(c)): {inspect.isclass(_unwrapped_call(c))}")
print(f"isclass(_impartial(p)): {inspect.isclass(_impartial(p))}")
print(f"isclass(_unwrapped_call(p)): {inspect.isclass(_unwrapped_call(p))}")
print(f"isclass(_impartial(w)): {inspect.isclass(_impartial(w))}")
print(f"isclass(_unwrapped_call(w)): {inspect.isclass(_unwrapped_call(w))}")
